#define time iTime
#define v2Resolution iResolution

#define sm smoothstep
#define nn normalize
#define r2(a)mat2(cos(a),-sin(a),sin(a),cos(a))


const float pi=acos(-1.),bpm=133./60.;
vec4 s,t;

vec2 m2(vec2 m, float d, int i)
{
        if (d < m.x) m=vec2(d,i);return m;
}

float sd_box(vec3 p, vec3 e)
{
        p = abs(p) - e;
        return length(max(p,0.0)) + min(max(p.x,max(p.y,p.z)),0.0);
}
float sd_oct(vec3 p, float s)
{
        p=abs(p);
        float m=p.x+p.y+p.z-s;
        vec3 o=p-m/3.,k=min(o,.0);
        return length(p-clamp(o+(k.x+k.y+k.z)*.5-k*1.5,.0,s))*sign(m);
}

float smin(float a, float b, float f){float h=clamp(0.5+0.5*(b-a)/f,0.,1.);return mix(b,a,h)-f*h*(1.-h);}
float ez(float x, float f) {return .5*pow((2.*min(x,1.-x)), f)*sign(0.5-x)+step(.5,x);}
float ea(float x, float f) {return ez(fract(2.*x),f)*sign(0.5-x)+step(.5,x); }

float mw(vec3 p){
        float d = 1e9;
        float m = 0.;
        if (s.z > 8. && s.z < 9.) m = ez(t.z,4.);
        if (s.z > 9. && s.z < 10.) m = 1.-ez(t.z,4.);
        if (s.z > 12. && s.z < 15.) m = 1.;
        if (s.z > 15. && s.z < 16.) m = 1.-smoothstep(0.,.5,t.z);
        if (s.z > 20. && s.z < 23.) m = 1.-ez(t.y,3.);
        {
                d = min(d, length(p)-mix(3.,0.,m));
        }
        if (m > 0.)
        {
                vec3 q = p - 2.*clamp(round(p/2.), -1.,1.);
                d = smin(d, length(q)-mix(0.,.5,m), mix(.9, .1, m));
        }


        float dd = length(p.xyz);
        float f = 1.;
        if (s.z>23.&&s.z<27.)
                f = mix(2.,1.,pow(t.x,4.));
        if (s.z > 4. && (!(s.z>10.&&s.z<12.)))
        p.xz *= r2(.05*pi*(pow(t.x,3.)+floor(s.x)));
        p+=.5*sin(s.y);
        p*=2.;d+=.2*f*(sin(p.x)*sin(p.y)*sin(p.z));
        p*=2.;d+=.1*f*(sin(p.x)*sin(p.y)*sin(p.z));

        if(!(s.z>10.&&s.z<12.))
        {
        p.y-=pow(t.x,4.);
        p*=4.;d+=.1*pow(abs(sin(dd*4.-(s.y+.5)*pi)),8.)* (sin(p.x)*sin(p.y)*sin(p.z));
        }

        return d;
}
uint sr;
vec2 map(vec3 p, float si, int m)
{
        vec2 md=vec2(1e9,0);
        float d = 1e9;
        if(0!=(m&2))
        {//mirror
                if ((s.z < 12.)||(s.z>14.&&s.z<20.)||(s.z>25.&&s.z<28.))
                {//pyramid
                        vec3 q=p;

                        q = abs(q);
                        q.xz *= r2(.25*pi);
                        q.x*=0.01;
                        if (s.z < 4.) {
                        q.yz -= 2.+min(floor(s.x),32.)/8.;
                        md=m2(md, sd_oct(q, 2.), 2);
                        }
                        else {
                        q.yz -= 6.;
                        md=m2(md, sd_oct(q, 4.), 2);
                        }
                }
        }
        if(0!=(m&4))
        { /* water */
                md=m2(md, mw(p)*si, 4);
        }
        if(0!=(m&8))
        {
                if ((s.z > 20. && s.z<22.) && (t.y<.5) || (s.z > 22. && s.z<23.))
                if (fract(4.*t.x)>.5&&sr!=0u)
                {//cross
                        vec3 q = p;
                        q.xz *= r2(.25*pi);
                        vec2 th;
                        if (s.z>23.) {
                                th=vec2(.5,.025);
                                q-=4.*clamp(round(q/4.),-2.,2.);
                        } else {
                                th=vec2(.25,.025);
                                q-=4.*clamp(round(q/4.),-1.,1.);
                        }
                        d=sd_box(q, th.xyy);
                        d=min(d,sd_box(q, th.yxy));
                        d=min(d,sd_box(q, th.yyx));
                }
                if ((s.z>20.&&s.z<23.&& t.y > .5))
                {// big-cross
                vec3 q = p;
                float t=.01;
                q.xz *= r2(.25*pi);
                q=abs(q);
                d=min(d, sd_box(q, vec3(3,t,t)));
                d=min(d, sd_box(q, vec3(t,3,t)));
                d=min(d, sd_box(q, vec3(t,t,3)));
                }
                if ((s.z>12.&&s.z<18.)||(s.z>23.&&s.z<27.5))
                {// arrow laser
                vec3 q=p;
                vec2 th=vec2(2,0.05);
                q = abs(q);
                q.xz *= r2(.25*pi);
                q.yz *= r2(.25*pi);
                q.z -= 4.;
                if (s.z < 1.)
                        q.x-=clamp(round(q.x),-10.,10.);
                else {
                        q.z+=2.*pow(2.*fract(2.*t.y),3.);
                }

                d=min(d, sd_box(q, th.yyx));
                }
                if ((s.z<4.)||(s.z>20.&&s.z<22.&& t.y > .5)||(s.z > 25.))
                {// neon
                vec3 q=p;
                vec2 th=vec2(2,.1);
                q = abs(q);
                q.xz *= r2(.25*pi);
                q.yz *= r2(.25*pi);

                if (s.z<4.) {
                q.x-=clamp(round(q.x),-3.,3.);
                q.z -= .5+min(floor(s.x),32.)/8.;
                } else  if (s.z>25.) {
                        float i = floor(mix(2.,0.,fract(s.x/2.)));
                        if (s.z<27.) i = 3.;
                        q.x-=clamp(round(q.x),-i,i);
                q.z -= 4.5;
                }
                else    q.z -= 9.;
                d=min(d, sd_box(q, th.yyx));
                }
                if ((s.z > 4. && s.z < 12.) || (s.z>18.&&s.z<20.)
        )
                {// neon py
                vec3 q=p;
                if (!(s.z>10.&&s.z<12.)&&s.z<18.)
                q.xz *= r2(.5*pi*(pow(t.y,8.)+floor(s.y+.45)));
                vec2 th=vec2(2,.1);
                if (s.z < 10.) th.y *= (1.-t.x);
                q = abs(q);
                q.xz *= r2(.25*pi);
                q.yz *= r2(.25*pi);
                float i=5.;
                if (s.z>4.&&s.z<6.)i=2.;
                if (s.z>6.&&s.z<10.)i=3.5;
                if (s.z>10.&&s.z<12.||s.z>18.) { i=1.; th.y *= .25; }
                q.z-=i;
                d=min(d, sd_box(q, th.yyx));
                }
                md=m2(md, d, 8);
        }

        return md;
}

vec3 nrm(vec3 p, float s, int m) {
        vec2 e;
        e=vec2(5e-4,-5e-4);
        m=0xff;
        return normalize(
                e.xyy*map(p+e.xyy,s,m).x+
                e.yyx*map(p+e.yyx,s,m).x+
                e.yxy*map(p+e.yxy,s,m).x+
                e.xxx*map(p+e.xxx,s,m).x
                );
}
vec3 raym(vec3 ro, vec3 rd) {
        float ff = .02, tf = 2.; // [0; 100] opacity
        float wi = 1.4;
        vec3 o;
        float w=1.,d,r=0.,t=0.,f=0.;
        vec3 n,q,p=ro+rd*r;
        int i,h,m=0;
        vec2 rr;
        float s=sign(map(p,1.,0xf)).x;

        for(i=h=0;i<100;i++){
                m=0xf;
                p=ro+rd*r;

                rr=map(p,s,m);

                d=rr.x;m=int(rr.y);
                r+=d*.8;
                if (m==4 && d<1e-3 && h<8){
                        n = nrm(p,s,m);
                        ro = ro+rd*r;
                        rd = refract(q = rd,n,max(s/wi,-s*wi));
                        f+=max(s*r,0.); // fog
                        if (dot(rd,rd)<1e-4)
                                rd = reflect(q,n);
                        t+=max(-s*r*.8,0.); // tint
                        s=-s;
                        r=5e-3;
                        h++;
                        continue;
                }
                if (m==2 && d<1e-3 && h<8){
                        n = nrm(p,s,m);
                        w*=1.-pow(1.-dot(-rd,n),.1);
                        ro = ro+rd*r;
                        rd = q = reflect(rd,n);
                        f+=max(s*r,0.);
                        r=5e-3;
                        h++;
                        continue;
                }

                if(d<1e-3||r>1e2)break;
        }
        if (s<0.)t+=r+d+0.2;
#if 0
        if (m==8) o = vec3(1);
#endif
        o = vec3(m==8);

        o=o*w;
        t = exp(-tf*t*t);
        o = mix(vec3(0), o, clamp(t,0.,1.));
        f += r;
        f = exp(-ff*f*f);
        o = mix(vec3(0), o, clamp(f,0.,1.));
        return o;
}

void mainImage(out vec4 o_col, in vec2 i_fragcoord){
        // globals
        s=bpm*time/vec4(1.,4.,16.,64.),t=fract(s);
        sr = ((t.z < 0.25 ? 0xe28aa388u :
           t.z < 0.50 ? 0xa28af288u :
           t.z < 0.75 ? 0xe28aa388u : 0xa28af2aau
                   )) & uint(1<<(32-int(fract(s.z*4.)*32.)));
        // main
        vec2 uv = (i_fragcoord.xy-.5*v2Resolution.xy)/v2Resolution.y;
        vec3 bg=vec3(.0);
        vec3 col=bg;
        vec3 at,ro;

        at=vec3(0);
        ro=vec3(100);
        ro = vec3(4.*sin(.5*pi*t.z),.5+2.*sin(pi*t.z),mix(-5.,-3.,t.z));
        if (s.z<2.) { ro = vec3(0,0,mix(-15.,-5.,s.z/2.)); }
        if (s.z>2.&&s.z<4.) { ro = vec3(mix(0.,-4.,(s.z-2.)/2.),0,mix(-5.,-3.,(s.z-2.)/2.)); }
        if (s.z>5.&&s.z<7.) { ro=vec3(mix(-2.,2.,(s.z-5.)/2.),mix(2.,-2.,(s.z-5.)/2.),-3.5); at = vec3(mix(4.,-4.,(s.z-5.)/2.),-4.,0.);}

        if (s.z>6.&&s.z<8.) { ro = vec3(4.*sin(.5*pi*t.z),.5+2.*sin(pi*t.z),mix(-5.,-3.,t.z)); }
        if (s.z>10.&&s.z<12.) { ro=vec3(0,2.*sin(pi*fract(s.z/2.)),mix(-10.,-5.,fract(s.z/2.))); }
        if (s.z>13.&&s.z<14.) { ro=vec3(sin(pi*t.z),-2.,cos(pi*t.z)); }
        if (s.z>14.&&s.z<15.) { ro=vec3(0,mix(10.,3.,floor(t.z*8.)/8.),.01); }
        if (s.z>15.&&s.z<16.) { ro=vec3(0,mix(3.,1.,t.z),mix(0.,10.,t.z)); }
        if (s.z>15.&&s.z<16.) { ro=vec3(0,0,mix(5.,9.,t.z)); }
        if (s.z>16.&&s.z<17.) { ro=vec3(0,0,mix(16.,8.,pow(t.z,.5))); }
        if (s.z>17.&&s.z<18.) { ro=vec3(mix(3.,-3.,t.z),mix(3.,-3.,t.z),-4.); at = vec3(mix(-3.,3.,t.z),-4.,0.);}
        if (s.z>18.&&s.z<20.) { ro=vec3(0,sin(pi*fract(s.z/2.)),mix(-16.,-4.,pow(fract(s.z/2.),.4))); }
        if (s.z>25.&&s.z<26.) { ro=vec3(0,0,mix(5.,10.,t.z)); }
        if (s.z>26.&&s.z<28.) { ro=vec3(0,0,mix(10.,20.,fract(s.z/2.))); }
        if (s.z > 27.125) { o_col = vec4(0,0,0,1); return; }
        vec3 cf=normalize(at-ro);
        vec3 cl=normalize(cross(cf,vec3(0,1,0)));
        vec3 cu=normalize(cross(cl,cf));
        vec3 rd;

        rd=mat3(cl,cu,cf)*normalize(vec3(uv,.5));
        col=raym(ro,rd);

        float p = 0.;
        if (s.z > 10.02 && s.z < 12.) p = 1.;
        if (s.z > 18.02 && s.z < 20.) p = 1.;
        col=pow(col,vec3(mix(.1
                             *((s.z>20.&&s.z<23.) ? t.x : 1.)
                             ,.0001,p)));
        if (s.z>20.&&s.z<23.)
        {
                float f = 1.-step(.5,1.-length(uv/1.5*2.));
                f*=step(.5,t.y);
                col = mix(col, 1.-col, f);
        }

        o_col = vec4(col, mix(mix(.8,.2,
                s.z>17. && s.z<23. ? smoothstep(.75,1.,t.y) : 0.), 0.05*col.r,p));
        //alpha blending
        vec4 p_col = texelFetch(iChannel1, ivec2(i_fragcoord), 0);
        o_col.rgb = mix(p_col.rgb, o_col.rgb, o_col.a);
}
